"""Construct the v28 lifecycle script from the immutable v27 source checked out on this branch."""
import base64,zlib
from pathlib import Path
SOURCE=Path("experiments/locomo_live_capture_v27.py")
DEST=Path("experiments/locomo_live_capture_v28.py")
assert SOURCE.exists()
DEST.write_bytes(SOURCE.read_bytes())
patch=zlib.decompress(base64.b64decode("")).decode()
patch=patch.replace("Path('/mnt/data/coling_v28_work/experiments/locomo_live_capture_v28.py')","Path('experiments/locomo_live_capture_v28.py')")
exec(compile(patch,"<v28-patch>","exec"))
